import React, { useState } from 'react';
import { Course, StudentResult, GradeLevel, StudentAccount } from '../types';
import { GRADE_GROUPS } from '../constants';

interface TeacherDashboardProps {
  username: string;
  assignedGrades: GradeLevel[];
  allStudents: StudentAccount[];
  courses: Course[];
  results: StudentResult[];
  onAddCourse: (name: string, grade: GradeLevel, description: string) => void;
  onAddResult: (result: Omit<StudentResult, 'id' | 'date' | 'teacherName'>) => void;
}

export const TeacherDashboard: React.FC<TeacherDashboardProps> = ({
  username,
  assignedGrades,
  allStudents,
  courses,
  results,
  onAddCourse,
  onAddResult
}) => {
  const [activeTab, setActiveTab] = useState<'overview' | 'courses' | 'students' | 'grading'>('overview');

  // Course form state
  const [courseName, setCourseName] = useState('');
  const [courseGrade, setCourseGrade] = useState<GradeLevel>(assignedGrades[0] || 'Primary 1');
  const [courseDesc, setCourseDesc] = useState('');

  // Grading form state
  const [selectedStudent, setSelectedStudent] = useState<string>('');
  const [selectedSubject, setSelectedSubject] = useState<string>('');
  const [score, setScore] = useState<number>(0);
  const [term, setTerm] = useState<string>('First Term');

  const filteredStudents = allStudents.filter(s => assignedGrades.includes(s.grade));
  const myResults = results.filter(r => r.teacherName === username);

  const handleAddCourse = (e: React.FormEvent) => {
    e.preventDefault();
    if (courseName) {
      onAddCourse(courseName, courseGrade, courseDesc);
      setCourseName('');
      setCourseDesc('');
      alert("New course added to curriculum!");
    }
  };

  const handleAddGrade = (e: React.FormEvent) => {
    e.preventDefault();
    const student = allStudents.find(s => s.id === selectedStudent);
    if (student && selectedSubject) {
      onAddResult({
        studentName: student.name,
        grade: student.grade,
        subject: selectedSubject,
        score: score,
        term: term
      });
      setScore(0);
      alert(`Result for ${student.name} recorded!`);
    }
  };

  return (
    <div className="bg-white rounded-[2.5rem] shadow-2xl overflow-hidden border-4 border-yellow-400">
      <div className="bg-blue-900 px-10 py-12 text-white relative">
        <div className="relative z-10">
          <h2 className="text-4xl font-black mb-2 font-serif">Welcome, {username}</h2>
          <div className="flex flex-wrap gap-2 mt-4">
            {assignedGrades.map(g => (
              <span key={g} className="px-3 py-1 bg-yellow-400 text-blue-900 rounded-lg text-[10px] font-black uppercase tracking-tighter shadow-md">
                Class: {g}
              </span>
            ))}
          </div>
          <p className="text-blue-200 font-bold uppercase text-xs tracking-[0.2em] mt-4">Academic Staff Portal • God's Hand School</p>
        </div>
      </div>

      <div className="flex flex-wrap border-b-2 border-slate-100 bg-slate-50">
        {[
          { id: 'overview', label: 'Summary' },
          { id: 'students', label: 'My Students' },
          { id: 'courses', label: 'Curriculum' },
          { id: 'grading', label: 'Grading' }
        ].map(tab => (
          <button 
            key={tab.id}
            onClick={() => setActiveTab(tab.id as any)}
            className={`px-8 py-6 font-black text-sm uppercase tracking-widest transition-all ${activeTab === tab.id ? 'text-blue-900 border-b-4 border-blue-900 bg-white' : 'text-slate-400 hover:text-blue-700'}`}
          >
            {tab.label}
          </button>
        ))}
      </div>

      <div className="p-10">
        {activeTab === 'overview' && (
          <div className="grid md:grid-cols-4 gap-8">
            <div className="p-8 bg-blue-50 rounded-3xl border-2 border-blue-100">
               <p className="text-slate-500 font-bold text-xs uppercase tracking-widest mb-2">My Students</p>
               <p className="text-5xl font-black text-blue-900">{filteredStudents.length}</p>
            </div>
            <div className="p-8 bg-yellow-50 rounded-3xl border-2 border-yellow-100">
               <p className="text-slate-500 font-bold text-xs uppercase tracking-widest mb-2">Total Courses</p>
               <p className="text-5xl font-black text-blue-900">{courses.length}</p>
            </div>
            <div className="p-8 bg-indigo-50 rounded-3xl border-2 border-indigo-100">
               <p className="text-slate-500 font-bold text-xs uppercase tracking-widest mb-2">Results Uploaded</p>
               <p className="text-5xl font-black text-blue-900">{myResults.length}</p>
            </div>
            <div className="p-8 bg-green-50 rounded-3xl border-2 border-green-100">
               <p className="text-slate-500 font-bold text-xs uppercase tracking-widest mb-2">Portal Status</p>
               <p className="text-2xl font-black text-green-700 uppercase">ONLINE</p>
            </div>
          </div>
        )}

        {activeTab === 'students' && (
          <div className="space-y-8">
            <h3 className="text-2xl font-black text-blue-900 font-serif">Class Registers</h3>
            {assignedGrades.length === 0 ? (
              <div className="p-12 text-center bg-slate-50 rounded-3xl border-2 border-dashed border-slate-200 text-slate-400 font-bold uppercase text-xs tracking-widest">No classes assigned to you yet.</div>
            ) : (
              <div className="grid gap-8">
                {assignedGrades.map(grade => {
                  const studentsInGrade = filteredStudents.filter(s => s.grade === grade);
                  return (
                    <div key={grade} className="bg-white rounded-3xl border-2 border-slate-100 overflow-hidden shadow-sm">
                      <div className="bg-slate-50 px-8 py-4 border-b-2 border-slate-100 flex justify-between items-center">
                        <h4 className="font-black text-blue-900 uppercase tracking-widest">{grade}</h4>
                        <span className="px-3 py-1 bg-blue-900 text-yellow-400 text-[10px] font-black rounded-full">{studentsInGrade.length} Students</span>
                      </div>
                      <div className="divide-y divide-slate-50">
                        {studentsInGrade.length === 0 ? (
                          <p className="p-8 text-center text-slate-400 text-xs font-bold uppercase tracking-widest italic">No students registered in this grade yet.</p>
                        ) : (
                          studentsInGrade.map(student => (
                            <div key={student.id} className="p-6 flex items-center justify-between hover:bg-slate-50 transition-colors">
                              <div className="flex items-center">
                                <div className="w-12 h-12 bg-yellow-100 text-blue-900 rounded-2xl flex items-center justify-center font-black mr-4 border-2 border-yellow-200">
                                  {student.name.charAt(0)}
                                </div>
                                <div>
                                  <p className="font-black text-blue-900 text-lg">{student.name}</p>
                                  <p className="text-xs text-slate-500 font-medium">{student.email}</p>
                                </div>
                              </div>
                              <div className="text-right">
                                <p className="text-[10px] text-slate-400 font-black uppercase tracking-widest mb-1">Enrolled Since</p>
                                <p className="text-xs font-bold text-blue-900">{new Date(student.createdAt).toLocaleDateString()}</p>
                              </div>
                            </div>
                          ))
                        )}
                      </div>
                    </div>
                  );
                })}
              </div>
            )}
          </div>
        )}

        {activeTab === 'courses' && (
          <div className="grid lg:grid-cols-2 gap-16">
             <div>
               <h3 className="text-2xl font-black text-blue-900 mb-8 font-serif">Contribute to Curriculum</h3>
               <form onSubmit={handleAddCourse} className="space-y-6 bg-slate-50 p-8 rounded-3xl border-2 border-slate-100">
                  <div className="space-y-2">
                    <label className="text-xs font-black text-slate-400 uppercase tracking-widest">Subject Title</label>
                    <input 
                      type="text" 
                      required
                      value={courseName}
                      onChange={(e) => setCourseName(e.target.value)}
                      placeholder="e.g. Basic Science"
                      className="w-full px-4 py-4 bg-white border-2 border-slate-200 rounded-2xl font-bold focus:ring-4 focus:ring-blue-100 outline-none"
                    />
                  </div>
                  <div className="space-y-2">
                    <label className="text-xs font-black text-slate-400 uppercase tracking-widest">Class / Grade</label>
                    <select 
                      value={courseGrade}
                      onChange={(e) => setCourseGrade(e.target.value as GradeLevel)}
                      className="w-full px-4 py-4 bg-white border-2 border-slate-200 rounded-2xl font-bold focus:ring-4 focus:ring-blue-100 outline-none"
                    >
                      {assignedGrades.map(lvl => (
                        <option key={lvl} value={lvl}>{lvl}</option>
                      ))}
                    </select>
                  </div>
                  <div className="space-y-2">
                    <label className="text-xs font-black text-slate-400 uppercase tracking-widest">Course Objective</label>
                    <textarea 
                      value={courseDesc}
                      onChange={(e) => setCourseDesc(e.target.value)}
                      rows={3}
                      className="w-full px-4 py-4 bg-white border-2 border-slate-200 rounded-2xl font-bold focus:ring-4 focus:ring-blue-100 outline-none"
                      placeholder="What will students learn?"
                    />
                  </div>
                  <button type="submit" className="w-full py-5 bg-blue-900 text-yellow-400 font-black text-lg rounded-2xl shadow-xl hover:bg-blue-800 transition-all">
                    Register New Subject
                  </button>
               </form>
             </div>

             <div className="space-y-6">
                <h3 className="text-2xl font-black text-blue-900 font-serif">Academic Course List</h3>
                <div className="space-y-4 max-h-[500px] overflow-y-auto pr-2 custom-scrollbar">
                  {courses.map(course => (
                    <div key={course.id} className="p-6 bg-white border-2 border-slate-100 rounded-2xl flex justify-between items-center group hover:border-blue-200 transition-colors">
                      <div>
                        <p className="font-black text-blue-900 text-lg">{course.name}</p>
                        <p className="text-xs text-slate-500">{course.description}</p>
                      </div>
                      <span className="text-[10px] font-black uppercase bg-blue-100 text-blue-800 px-3 py-1 rounded-full">{course.grade}</span>
                    </div>
                  ))}
                </div>
             </div>
          </div>
        )}

        {activeTab === 'grading' && (
           <div className="grid lg:grid-cols-2 gap-16">
              <div>
                <h3 className="text-2xl font-black text-blue-900 mb-8 font-serif">Record Assessment</h3>
                <form onSubmit={handleAddGrade} className="space-y-6 bg-blue-50 p-8 rounded-[2rem] border-2 border-blue-100 shadow-sm">
                  <div className="space-y-2">
                    <label className="text-xs font-black text-blue-900 uppercase tracking-widest">Select Student</label>
                    <select 
                      required
                      value={selectedStudent}
                      onChange={(e) => setSelectedStudent(e.target.value)}
                      className="w-full px-4 py-4 bg-white border-2 border-blue-100 rounded-2xl font-bold outline-none"
                    >
                      <option value="">-- Choose Student --</option>
                      {filteredStudents.map(s => (
                        <option key={s.id} value={s.id}>{s.name} ({s.grade})</option>
                      ))}
                    </select>
                  </div>

                  <div className="space-y-2">
                    <label className="text-xs font-black text-blue-900 uppercase tracking-widest">Subject</label>
                    <select 
                      required
                      value={selectedSubject}
                      onChange={(e) => setSelectedSubject(e.target.value)}
                      className="w-full px-4 py-4 bg-white border-2 border-blue-100 rounded-2xl font-bold outline-none"
                    >
                      <option value="">-- Choose Subject --</option>
                      {courses.map(c => (
                        <option key={c.id} value={c.name}>{c.name} ({c.grade})</option>
                      ))}
                    </select>
                  </div>

                  <div className="grid grid-cols-2 gap-4">
                    <div className="space-y-2">
                      <label className="text-xs font-black text-blue-900 uppercase tracking-widest">Score (0-100)</label>
                      <input 
                        type="number" min="0" max="100" required
                        value={score}
                        onChange={(e) => setScore(parseInt(e.target.value) || 0)}
                        className="w-full px-4 py-4 bg-white border-2 border-blue-100 rounded-2xl font-bold outline-none"
                      />
                    </div>
                    <div className="space-y-2">
                      <label className="text-xs font-black text-blue-900 uppercase tracking-widest">Academic Term</label>
                      <select 
                        value={term}
                        onChange={(e) => setTerm(e.target.value)}
                        className="w-full px-4 py-4 bg-white border-2 border-blue-100 rounded-2xl font-bold outline-none"
                      >
                        <option value="First Term">First Term</option>
                        <option value="Second Term">Second Term</option>
                        <option value="Third Term">Third Term</option>
                      </select>
                    </div>
                  </div>

                  <button type="submit" className="w-full py-5 bg-blue-900 text-yellow-400 font-black text-lg rounded-2xl shadow-xl hover:bg-blue-800 transition-all transform hover:-translate-y-1">
                    Upload Result
                  </button>
                </form>
              </div>

              <div className="space-y-6">
                <h3 className="text-2xl font-black text-blue-900 font-serif">Recently Uploaded</h3>
                <div className="space-y-4 max-h-[600px] overflow-y-auto pr-2 custom-scrollbar">
                  {myResults.length === 0 ? (
                    <div className="p-12 text-center bg-white rounded-3xl border-2 border-dashed border-slate-200 text-slate-400 font-bold uppercase text-xs tracking-widest">No results uploaded by you yet.</div>
                  ) : (
                    myResults.map(res => (
                      <div key={res.id} className="p-6 bg-white border-2 border-slate-100 rounded-2xl shadow-sm">
                        <div className="flex justify-between items-start mb-2">
                          <div>
                            <p className="font-black text-blue-900">{res.studentName}</p>
                            <p className="text-[10px] text-slate-400 font-black uppercase tracking-widest">{res.subject} • {res.term}</p>
                          </div>
                          <div className={`text-xl font-black ${res.score >= 50 ? 'text-green-600' : 'text-red-500'}`}>
                            {res.score}%
                          </div>
                        </div>
                      </div>
                    ))
                  )}
                </div>
              </div>
           </div>
        )}
      </div>
    </div>
  );
};

import React, { useState, useEffect } from 'react';
import { UserRole, AppState, StudentApplication, Announcement, TeacherAccount, StudentResult, Course, GradeLevel, StudentAccount } from './types';
import { stateService } from './services/stateService';
import { Header } from './components/Header';
import { Hero } from './components/Hero';
import { AdminPanel } from './components/AdminPanel';
import { StudentPortal } from './components/StudentPortal';
import { StudentAuth } from './components/StudentAuth';
import { AdminLoginGateway } from './components/AdminLoginGateway';
import { TeacherLoginGateway } from './components/TeacherLoginGateway';
import { Footer } from './components/Footer';
import { TeacherDashboard } from './components/TeacherDashboard';

const App: React.FC = () => {
  const [role, setRole] = useState<UserRole>(UserRole.GUEST);
  const [currentUser, setCurrentUser] = useState<string | null>(null);
  const [state, setState] = useState<AppState>(stateService.getState());
  const [view, setView] = useState<'home' | 'portal' | 'apply' | 'admin' | 'teacherLogin' | 'teacher' | 'studentAuth'>('home');
  const [loginError, setLoginError] = useState('');

  useEffect(() => {
    stateService.saveState(state);
  }, [state]);

  const updateFees = (grade: string, amount: number) => {
    setState(prev => ({
      ...prev,
      fees: { ...prev.fees, [grade]: amount }
    }));
  };

  const updateCalendar = (content: string) => {
    setState(prev => ({
        ...prev,
        academicCalendar: content
    }));
  };

  const addAnnouncement = (title: string, content: string) => {
    const newAnn: Announcement = {
      id: Date.now().toString(),
      title,
      content,
      date: new Date().toLocaleDateString()
    };
    setState(prev => ({
      ...prev,
      announcements: [newAnn, ...prev.announcements]
    }));
  };

  const addCourse = (name: string, grade: GradeLevel, description: string) => {
    const newCourse: Course = {
      id: 'CRS-' + Date.now(),
      name,
      grade,
      description
    };
    setState(prev => ({
      ...prev,
      courses: [...prev.courses, newCourse]
    }));
  };

  const addResult = (resultData: Omit<StudentResult, 'id' | 'date' | 'teacherName'>) => {
    const newResult: StudentResult = {
      ...resultData,
      id: 'RES-' + Date.now(),
      date: new Date().toLocaleDateString(),
      teacherName: currentUser || 'Unknown Teacher'
    };
    setState(prev => ({
      ...prev,
      results: [newResult, ...prev.results]
    }));
  };

  const createStudentAccount = (account: Omit<StudentAccount, 'id' | 'createdAt'>) => {
    if (state.studentAccounts.some(s => s.email === account.email)) {
      setLoginError("An account with this email already exists.");
      return;
    }
    const newAccount: StudentAccount = {
      ...account,
      id: 'STU-' + Date.now(),
      createdAt: new Date().toISOString()
    };
    setState(prev => ({
      ...prev,
      studentAccounts: [...prev.studentAccounts, newAccount]
    }));
    setRole(UserRole.STUDENT);
    setCurrentUser(newAccount.name);
    setView('portal');
    setLoginError('');
  };

  const handleStudentLogin = (email: string, pass: string) => {
    const student = state.studentAccounts.find(s => s.email === email && s.password === pass);
    if (student) {
      setRole(UserRole.STUDENT);
      setCurrentUser(student.name);
      setView('portal');
      setLoginError('');
    } else {
      setLoginError("Invalid student credentials.");
    }
  };

  const submitApplication = (app: Omit<StudentApplication, 'id' | 'timestamp' | 'paid'>) => {
    const newApp: StudentApplication = {
      ...app,
      id: 'APP-' + Math.random().toString(36).substr(2, 9).toUpperCase(),
      timestamp: new Date().toISOString(),
      paid: true
    };
    setState(prev => ({
      ...prev,
      applications: [newApp, ...prev.applications]
    }));
    return newApp;
  };

  const createTeacherAccount = (teacher: Omit<TeacherAccount, 'id' | 'createdAt'>) => {
    const newTeacher: TeacherAccount = {
      ...teacher,
      id: 'TEA-' + Date.now(),
      createdAt: new Date().toISOString()
    };
    setState(prev => ({
      ...prev,
      teachers: [...prev.teachers, newTeacher]
    }));
  };

  const handleAdminLoginAttempt = (email: string, password: string) => {
    if (email.trim().length > 0 && password === '197005') {
      setRole(UserRole.ADMIN);
      setCurrentUser(email);
      setLoginError('');
      setView('admin');
      return;
    } 
    setLoginError('Invalid admin email or security key.');
  };

  const handleTeacherLoginAttempt = (username: string, password: string) => {
    const teacher = state.teachers.find(t => t.username === username && t.password === password);
    if (teacher) {
      setRole(UserRole.TEACHER);
      setCurrentUser(teacher.username);
      setView('teacher');
      setLoginError('');
      return;
    }
    setLoginError('Incorrect teacher username or password.');
  };

  const handleNav = (v: any) => {
    if ((v === 'apply' || v === 'portal') && role === UserRole.GUEST) {
        setLoginError("You must log in to access admission forms and school fees.");
        setView('studentAuth');
        return;
    }
    setLoginError('');
    setView(v);
  };

  // Find the logged-in teacher object to get assigned grades
  const currentTeacherObj = role === UserRole.TEACHER ? state.teachers.find(t => t.username === currentUser) : null;

  return (
    <div className="min-h-screen flex flex-col font-sans bg-slate-50">
      <Header 
        role={role} 
        setRole={setRole} 
        setView={handleNav} 
        activeView={view} 
      />

      <main className="flex-grow">
        {view === 'home' && (
          <Hero 
            announcements={state.announcements} 
            calendar={state.academicCalendar}
            onApply={() => handleNav('apply')}
          />
        )}

        {view === 'apply' && (
          <div className="max-w-4xl mx-auto py-12 px-4">
            <StudentPortal 
              fees={state.fees} 
              onSubmit={submitApplication} 
              onBack={() => setView('home')} 
            />
          </div>
        )}

        {view === 'studentAuth' && (
          <StudentAuth 
            onLogin={handleStudentLogin}
            onRegister={createStudentAccount}
            onBack={() => setView('home')}
            error={loginError}
          />
        )}

        {view === 'portal' && (
          <div className="max-w-4xl mx-auto py-12 px-4 text-center">
            <div className="bg-white p-12 rounded-2xl shadow-xl border border-yellow-400">
                <h2 className="text-3xl font-black text-blue-900 mb-4 font-serif leading-tight">Welcome Back, <br className="sm:hidden" /> {currentUser}!</h2>
                <p className="text-slate-600 mb-8 font-medium">Access your learning materials and check your results here.</p>
                <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
                    <button className="p-8 bg-blue-900 text-white rounded-xl hover:bg-blue-800 transition-all flex flex-col items-center group">
                        <span className="block text-4xl mb-2 text-yellow-400 group-hover:scale-110 transition-transform">📚</span>
                        <span className="font-black uppercase text-xs tracking-widest">Active Courses</span>
                    </button>
                    <button 
                        onClick={() => setView('apply')}
                        className="p-8 bg-yellow-400 text-blue-900 rounded-xl hover:bg-yellow-500 transition-all flex flex-col items-center group"
                    >
                        <span className="block text-4xl mb-2 group-hover:scale-110 transition-transform">₦</span>
                        <span className="font-black uppercase text-xs tracking-widest">Pay School Fees</span>
                    </button>
                </div>

                {/* Student Results Display */}
                <div className="mt-12 text-left">
                  <h3 className="text-xl font-black text-blue-900 mb-6 font-serif border-b-2 border-slate-50 pb-2">Your Performance Record</h3>
                  <div className="grid grid-cols-1 gap-4">
                    {state.results.filter(r => r.studentName === currentUser).length === 0 ? (
                      <p className="p-6 text-center text-slate-400 font-bold uppercase text-xs">No academic records available yet.</p>
                    ) : (
                      state.results.filter(r => r.studentName === currentUser).map(result => (
                        <div key={result.id} className="p-6 border border-slate-100 rounded-2xl flex justify-between items-center bg-slate-50">
                          <div>
                            <p className="font-black text-blue-900 text-lg">{result.subject}</p>
                            <p className="text-xs text-slate-500">{result.term} • Graded by {result.teacherName}</p>
                          </div>
                          <div className={`text-2xl font-black ${result.score >= 50 ? 'text-green-600' : 'text-red-500'}`}>
                            {result.score}%
                          </div>
                        </div>
                      ))
                    )}
                  </div>
                </div>

                <div className="mt-12 text-left">
                  <h3 className="text-xl font-black text-blue-900 mb-6 font-serif border-b-2 border-slate-50 pb-2">Academic Overview</h3>
                  <div className="grid grid-cols-1 gap-4">
                    {state.courses.map(course => (
                      <div key={course.id} className="p-6 border border-slate-100 rounded-2xl flex justify-between items-center bg-slate-50 hover:bg-white transition-colors group">
                        <div className="max-w-[70%]">
                          <p className="font-black text-blue-900 text-lg group-hover:text-yellow-600 transition-colors">{course.name}</p>
                          <p className="text-xs text-slate-500 font-medium truncate">{course.description}</p>
                        </div>
                        <span className="text-[10px] font-black uppercase bg-blue-100 text-blue-800 px-3 py-1 rounded-full text-nowrap">{course.grade}</span>
                      </div>
                    ))}
                  </div>
                </div>
            </div>
          </div>
        )}

        {view === 'teacherLogin' && (
          <TeacherLoginGateway 
            onLogin={handleTeacherLoginAttempt} 
            onBack={() => setView('home')} 
            error={loginError} 
          />
        )}

        {view === 'teacher' && role === UserRole.TEACHER && (
           <div className="max-w-6xl mx-auto py-12 px-4">
             <TeacherDashboard 
               username={currentUser || 'Staff'} 
               assignedGrades={currentTeacherObj?.assignedGrades || []}
               allStudents={state.studentAccounts}
               courses={state.courses}
               results={state.results}
               onAddCourse={addCourse}
               onAddResult={addResult}
             />
           </div>
        )}

        {view === 'admin' && (
          role === UserRole.ADMIN ? (
            <div className="max-w-6xl mx-auto py-12 px-4">
              <AdminPanel 
                fees={state.fees} 
                applications={state.applications}
                announcements={state.announcements}
                teachers={state.teachers}
                results={state.results}
                courses={state.courses}
                calendar={state.academicCalendar}
                onUpdateFee={updateFees}
                onAddAnnouncement={addAnnouncement}
                onCreateTeacher={createTeacherAccount}
                onAddCourse={addCourse}
                onUpdateCalendar={updateCalendar}
              />
            </div>
          ) : (
            <AdminLoginGateway 
              onLogin={handleAdminLoginAttempt}
              onBack={() => setView('home')}
              error={loginError}
            />
          )
        )}
      </main>

      <Footer />
    </div>
  );
};

export default App;

