                        <option value="First Term">First Term</option>
                        <option value="Second Term">Second Term</option>
                        <option value="Third Term">Third Term</option>
                      </select>
                    </div>
                  </div>

                  <button type="submit" className="w-full py-5 bg-blue-900 text-yellow-400 font-black text-lg rounded-2xl shadow-xl hover:bg-blue-800 transition-all transform hover:-translate-y-1">
                    Upload Result
                  </button>
                </form>
              </div>

              <div className="space-y-6">
                <h3 className="text-2xl font-black text-blue-900 font-serif">Recently Uploaded</h3>
                <div className="space-y-4 max-h-[600px] overflow-y-auto pr-2 custom-scrollbar">
                  {myResults.length === 0 ? (
                    <div className="p-12 text-center bg-white rounded-3xl border-2 border-dashed border-slate-200 text-slate-400 font-bold uppercase text-xs tracking-widest">No results uploaded by you yet.</div>
                  ) : (
                    myResults.map(res => (
                      <div key={res.id} className="p-6 bg-white border-2 border-slate-100 rounded-2xl shadow-sm">
                        <div className="flex justify-between items-start mb-2">
                          <div>
                            <p className="font-black text-blue-900">{res.studentName}</p>
                            <p className="text-[10px] text-slate-400 font-black uppercase tracking-widest">{res.subject} • {res.term}</p>
                          </div>
                          <div className={`text-xl font-black ${res.score >= 50 ? 'text-green-600' : 'text-red-500'}`}>
                            {res.score}%
                          </div>
                        </div>
                      </div>
                    ))
                  )}
                </div>
              </div>
           </div>
        )}
      </div>
    </div>
  );
};

{
  "name": "God's Hand School Management System",
  "description": "A comprehensive school management portal featuring a student admission system, fee management, and an administrative dashboard for the proprietor.",
  "requestFramePermissions": [
    "camera"
  ]
}

export enum UserRole {
  GUEST = 'GUEST',
  STUDENT = 'STUDENT',
  TEACHER = 'TEACHER',
  ADMIN = 'ADMIN'
}

export type GradeLevel = 
  | 'KG 1' | 'KG 2'
  | 'Nursery 1' | 'Nursery 2'
  | 'Primary 1' | 'Primary 2' | 'Primary 3' | 'Primary 4' | 'Primary 5'
  | 'JSS 1' | 'JSS 2' | 'JSS 3'
  | 'SSS 1' | 'SSS 2' | 'SSS 3';

export interface FeeStructure {
  [key: string]: number;
}

export interface Announcement {
  id: string;
  title: string;
  content: string;
  date: string;
}

export interface Course {
  id: string;
  name: string;
  grade: GradeLevel;
  description: string;
}

export interface StudentApplication {
  id: string;
  name: string;
  email: string;
  grade: GradeLevel;
  paid: boolean;
  timestamp: string;
}

export interface TeacherAccount {
  id: string;
  username: string;
  password: string;
  createdAt: string;
  assignedGrades: GradeLevel[];
  assignedCourses: string[]; // Array of Course IDs
}

export interface StudentAccount {
  id: string;
  name: string;
  email: string;
  password: string;
  grade: GradeLevel;
  createdAt: string;
}

export interface StudentResult {
  id: string;
  studentName: string;
  grade: GradeLevel;
  subject: string;
  score: number;
  term: string;
  teacherName: string;
  date: string;
}

export type PaymentType = 'full' | 'installment_1' | 'installment_2';

export interface FeePayment {
  id: string;
  studentId: string;
  studentName: string;
  amount: number;
  grade: GradeLevel;
  type: PaymentType;
  date: string;
}

export interface AttendanceRecord {
  studentId: string;
  date: string;
  markedBy: string;
}

export interface AppState {
  fees: FeeStructure;
  announcements: Announcement[];
  applications: StudentApplication[];
  teachers: TeacherAccount[];
  studentAccounts: StudentAccount[];
  results: StudentResult[];
  courses: Course[];
  payments: FeePayment[];
  attendance: AttendanceRecord[];
  academicCalendar: string;
}

import { AppState } from '../types';
import { INITIAL_FEES, APP_STORAGE_KEY } from '../constants';

const DEFAULT_STATE: AppState = {
  fees: INITIAL_FEES,
  announcements: [
    {
      id: '1',
      title: 'Welcome to the New Session',
      content: 'We are excited to welcome all students back to campus. God is our strength!',
      date: new Date().toLocaleDateString()
    }
  ],
  applications: [],
  teachers: [],
  studentAccounts: [],
  payments: [],
  attendance: [],
  courses: [
    { id: 'c1', name: 'Mathematics', grade: 'Primary 1', description: 'Basic arithmetic and numbers.' },
    { id: 'c2', name: 'English Language', grade: 'Primary 1', description: 'Grammar and phonetics.' }
  ],
  results: [
    {
      id: 'res-1',
      studentName: 'Chidi Okafor',
      grade: 'Primary 3',
      subject: 'Mathematics',
      score: 88,
      term: 'First Term',
      teacherName: 'Mr. Benson',
      date: new Date().toLocaleDateString()
    }
  ],
  academicCalendar: `1. Resumption: Jan 10th\n2. Mid-Term Break: Feb 15th - 17th\n3. Examination Period: March 20th - 30th\n4. Vacation: April 5th`
};

export const stateService = {
  getState: (): AppState => {
    const saved = localStorage.getItem(APP_STORAGE_KEY);
    if (saved) {
      try {
        const parsed = JSON.parse(saved);
        return {
          ...DEFAULT_STATE,
          ...parsed,
          teachers: parsed.teachers || [],
          studentAccounts: parsed.studentAccounts || [],
          payments: parsed.payments || [],
          attendance: parsed.attendance || [],
          courses: parsed.courses || DEFAULT_STATE.courses,
          results: parsed.results || DEFAULT_STATE.results,
          academicCalendar: parsed.academicCalendar || DEFAULT_STATE.academicCalendar
        };
      } catch (e) {
        console.error("Failed to parse state", e);
      }
    }
    return DEFAULT_STATE;
  },

  saveState: (state: AppState): void => {
    localStorage.setItem(APP_STORAGE_KEY, JSON.stringify(state));
  }
};

import React, { useState, useEffect } from 'react';
import { UserRole, AppState, StudentApplication, Announcement, TeacherAccount, StudentResult, Course, GradeLevel, StudentAccount, FeePayment, AttendanceRecord } from './types';
import { stateService } from './services/stateService';
import { Header } from './components/Header';
import { Hero } from './components/Hero';
import { AdminPanel } from './components/AdminPanel';
import { StudentPortal } from './components/StudentPortal';
import { StudentAuth } from './components/StudentAuth';
import { AdminLoginGateway } from './components/AdminLoginGateway';
import { TeacherLoginGateway } from './components/TeacherLoginGateway';
import { Footer } from './components/Footer';
import { TeacherDashboard } from './components/TeacherDashboard';
import { QRCodeSVG } from 'https://esm.sh/qrcode.react';

const App: React.FC = () => {
  const [role, setRole] = useState<UserRole>(UserRole.GUEST);
  const [currentUser, setCurrentUser] = useState<string | null>(null);
  const [state, setState] = useState<AppState>(stateService.getState());
  const [view, setView] = useState<'home' | 'portal' | 'apply' | 'admin' | 'teacherLogin' | 'teacher' | 'studentAuth'>('home');
  const [loginError, setLoginError] = useState('');
  const [showQRModal, setShowQRModal] = useState(false);

  useEffect(() => {
    stateService.saveState(state);
  }, [state]);

  const updateFees = (grade: string, amount: number) => {
    setState(prev => ({
      ...prev,
      fees: { ...prev.fees, [grade]: amount }
    }));
  };

  const updateCalendar = (content: string) => {
    setState(prev => ({
        ...prev,
        academicCalendar: content
    }));
  };

  const addAnnouncement = (title: string, content: string) => {
    const newAnn: Announcement = {
      id: Date.now().toString(),
      title,
      content,
      date: new Date().toLocaleDateString()
    };
    setState(prev => ({
      ...prev,
      announcements: [newAnn, ...prev.announcements]
    }));
  };

  const addCourse = (name: string, grade: GradeLevel, description: string) => {
    const newCourse: Course = {
      id: 'CRS-' + Date.now(),
      name,
      grade,
      description
    };
    setState(prev => ({
      ...prev,
      courses: [...prev.courses, newCourse]
    }));
  };

  const addResult = (resultData: Omit<StudentResult, 'id' | 'date' | 'teacherName'>) => {
    const newResult: StudentResult = {
      ...resultData,
      id: 'RES-' + Date.now(),
      date: new Date().toLocaleDateString(),
      teacherName: currentUser || 'Unknown Teacher'
    };
    setState(prev => ({
      ...prev,
      results: [newResult, ...prev.results]
    }));
  };

  const addPayment = (paymentData: Omit<FeePayment, 'id' | 'date'>) => {
    const newPayment: FeePayment = {
      ...paymentData,
      id: 'PAY-' + Math.random().toString(36).substr(2, 6).toUpperCase(),
      date: new Date().toISOString()
    };
    setState(prev => ({
      ...prev,
      payments: [newPayment, ...prev.payments]
    }));
    return newPayment;
  };

  const markAttendance = (studentId: string) => {
    const today = new Date().toLocaleDateString();
    const alreadyMarked = state.attendance.some(a => a.studentId === studentId && a.date === today);

    if (alreadyMarked) return false;

    const newRecord: AttendanceRecord = {
      studentId,
      date: today,
      markedBy: currentUser || 'System'
    };

    setState(prev => ({
      ...prev,
      attendance: [...prev.attendance, newRecord]
    }));
    return true;
  };

  const createStudentAccount = (account: Omit<StudentAccount, 'id' | 'createdAt'>) => {
    if (state.studentAccounts.some(s => s.email === account.email)) {
      setLoginError("An account with this email already exists.");
      return;
    }
    const newAccount: StudentAccount = {
      ...account,
      id: 'STU-' + Date.now(),
      createdAt: new Date().toISOString()
    };
    setState(prev => ({
      ...prev,
      studentAccounts: [...prev.studentAccounts, newAccount]
    }));
    setRole(UserRole.STUDENT);
    setCurrentUser(newAccount.name);
    setView('portal');
    setLoginError('');
  };

  const createTeacherAccount = (teacher: Omit<TeacherAccount, 'id' | 'createdAt'>) => {
    const newTeacher: TeacherAccount = {
      ...teacher,
      id: 'TCH-' + Date.now(),
      createdAt: new Date().toISOString()
    };
    setState(prev => ({
      ...prev,
      teachers: [...prev.teachers, newTeacher]
    }));
  };

  const handleStudentLogin = (email: string, pass: string) => {
    const student = state.studentAccounts.find(s => s.email === email && s.password === pass);
    if (student) {
      setRole(UserRole.STUDENT);
      setCurrentUser(student.name);
      setView('portal');
      setLoginError('');
    } else {
      setLoginError("Invalid student credentials.");
    }
  };

  const handleAdminLoginAttempt = (email: string, password: string) => {
    if (email.trim().length > 0 && password === '197005') {
      setRole(UserRole.ADMIN);
      setCurrentUser(email);
      setLoginError('');
      setView('admin');
      return;
    } 
    setLoginError('Invalid admin email or security key.');
  };

  const handleTeacherLoginAttempt = (username: string, password: string) => {
    const teacher = state.teachers.find(t => t.username === username && t.password === password);
    if (teacher) {
      setRole(UserRole.TEACHER);
      setCurrentUser(teacher.username);
      setView('teacher');
      setLoginError('');
      return;
    }
    setLoginError('Incorrect teacher username or password.');
  };

  const handleNav = (v: any) => {
    if ((v === 'apply' || v === 'portal') && role === UserRole.GUEST) {
        setLoginError("You must log in to access admission forms and school fees.");
        setView('studentAuth');
        return;
    }
    setLoginError('');
    setView(v);
  };

  const currentStudentObj = role === UserRole.STUDENT ? state.studentAccounts.find(s => s.name === currentUser) : null;
  const currentTeacherObj = role === UserRole.TEACHER ? state.teachers.find(t => t.username === currentUser) : null;

  const studentPayments = state.payments.filter(p => p.studentName === currentUser);
  const totalPaid = studentPayments.reduce((acc, p) => acc + p.amount, 0);
  const targetFee = currentStudentObj ? state.fees[currentStudentObj.grade] : 0;
  const paymentProgress = targetFee > 0 ? Math.min(100, Math.round((totalPaid / targetFee) * 100)) : 0;

  return (
    <div className="min-h-screen flex flex-col font-sans bg-slate-50">
      <Header 
        role={role} 
        setRole={setRole} 
        setView={handleNav} 
        activeView={view} 
      />

      <main className="flex-grow">
        {view === 'home' && (
          <Hero 
            announcements={state.announcements} 
            calendar={state.academicCalendar}
            onApply={() => handleNav('apply')}
          />
        )}

        {view === 'apply' && (
          <div className="max-w-4xl mx-auto py-12 px-4">
            <StudentPortal 
              fees={state.fees} 
              existingPayments={studentPayments}
              currentStudentId={currentStudentObj?.id || null}
              currentStudentName={currentStudentObj?.name || null}
              currentStudentGrade={currentStudentObj?.grade || null}
              onSubmit={addPayment} 
              onBack={() => setView(role === UserRole.STUDENT ? 'portal' : 'home')} 
            />
          </div>
        )}

        {view === 'studentAuth' && (
          <StudentAuth 
            onLogin={handleStudentLogin}
            onRegister={createStudentAccount}
            onBack={() => setView('home')}
            error={loginError}
          />
        )}

        {view === 'portal' && (
          <div className="max-w-4xl mx-auto py-12 px-4 text-center">
            <div className="bg-white p-10 rounded-[2.5rem] shadow-2xl border-2 border-slate-50 relative overflow-hidden">
                <div className="absolute top-0 left-0 w-full h-2 bg-yellow-400"></div>

                <div className="flex flex-col md:flex-row md:justify-between md:items-center mb-10 text-left">
                  <div>
                    <h2 className="text-4xl font-black text-blue-900 mb-1 font-serif">Welcome, {currentUser}</h2>
                    <p className="text-[10px] font-black text-slate-400 uppercase tracking-widest">Grade: {currentStudentObj?.grade} • Student ID: {currentStudentObj?.id}</p>
                  </div>
                  <div className="mt-6 md:mt-0 bg-blue-50 p-4 rounded-2xl border border-blue-100 min-w-[200px]">
                    <div className="flex justify-between text-[10px] font-black text-blue-900 uppercase tracking-widest mb-2">
                      <span>Payment Status</span>
                      <span>{paymentProgress}%</span>
                    </div>
                    <div className="w-full h-3 bg-white rounded-full overflow-hidden border border-blue-100">
                      <div className="h-full bg-blue-900 transition-all duration-1000" style={{ width: `${paymentProgress}%` }}></div>
                    </div>
                  </div>
                </div>

                <div className="grid grid-cols-1 md:grid-cols-3 gap-6">
                    <button 
                      onClick={() => setShowQRModal(true)}
                      className="p-10 bg-yellow-400 text-blue-900 rounded-[2rem] hover:bg-yellow-500 transition-all flex flex-col items-center group shadow-xl hover:-translate-y-1"
                    >
                        <span className="block text-5xl mb-3 group-hover:scale-110 transition-transform">🆔</span>
                        <span className="font-black uppercase text-xs tracking-widest">Attendance QR</span>
                    </button>
                    <button className="p-10 bg-blue-900 text-white rounded-[2rem] hover:bg-blue-800 transition-all flex flex-col items-center group shadow-xl hover:-translate-y-1">
                        <span className="block text-5xl mb-3 text-yellow-400 group-hover:scale-110 transition-transform">📚</span>
                        <span className="font-black uppercase text-xs tracking-widest">Materials</span>
                    </button>
                    <button 
                        onClick={() => setView('apply')}
                        className={`p-10 rounded-[2rem] transition-all flex flex-col items-center group shadow-xl hover:-translate-y-1 ${paymentProgress < 100 ? 'bg-indigo-600 text-white hover:bg-indigo-700' : 'bg-green-50 text-green-700 border-2 border-green-200 cursor-default'}`}
                    >
                        <span className="block text-5xl mb-3 group-hover:scale-110 transition-transform">
                          {paymentProgress < 100 ? '₦' : '✅'}
                        </span>
                        <span className="font-black uppercase text-xs tracking-widest">
                          {paymentProgress < 100 ? 'Pay Fees' : 'Fees Settled'}
                        </span>
                    </button>
                </div>

                {/* Modal for Attendance QR */}
                {showQRModal && currentStudentObj && (
                  <div className="fixed inset-0 z-[100] flex items-center justify-center p-4 bg-blue-900/80 backdrop-blur-sm">
                    <div className="bg-white rounded-[3rem] p-10 max-w-sm w-full text-center relative shadow-2xl animate-in zoom-in duration-300">
                      <button 
                        onClick={() => setShowQRModal(false)}
                        className="absolute top-6 right-6 text-slate-400 hover:text-red-500 font-black"
                      >
                        ✕
                      </button>
                      <h3 className="text-2xl font-black text-blue-900 mb-2 font-serif">Daily ID Pass</h3>
                      <p className="text-[10px] text-slate-400 font-bold uppercase tracking-widest mb-8">Show this to your teacher</p>

                      <div className="bg-slate-50 p-8 rounded-3xl inline-block border-4 border-slate-100 shadow-inner mb-8">
                        <QRCodeSVG 
                          value={`GHS-ATT-${currentStudentObj.id}`} 
                          size={180}
                          level="H"
                          includeMargin={true}
                        />
                      </div>

                      <div className="text-left space-y-2 bg-blue-50 p-6 rounded-2xl border border-blue-100">
                         <p className="text-xs font-black text-blue-900 uppercase">Student: <span className="text-slate-600 ml-1">{currentStudentObj.name}</span></p>
                         <p className="text-xs font-black text-blue-900 uppercase">Grade: <span className="text-slate-600 ml-1">{currentStudentObj.grade}</span></p>
                      </div>

                      <p className="text-[9px] text-slate-400 font-bold uppercase mt-8 leading-relaxed">
                        Hold your phone steady while the teacher scans this code to mark your presence.
                      </p>
                    </div>
                  </div>
                )}

                <div className="mt-16 grid md:grid-cols-2 gap-10 text-left">
                   <div>
                    <h3 className="text-xl font-black text-blue-900 mb-6 font-serif border-b-2 border-slate-50 pb-2">Academic Record</h3>
                    <div className="space-y-3">
                      {state.results.filter(r => r.studentName === currentUser).length === 0 ? (
                        <p className="p-8 text-center text-slate-300 font-black uppercase text-[10px] bg-slate-50 rounded-2xl border-2 border-dashed">No scores uploaded yet</p>
                      ) : (
                        state.results.filter(r => r.studentName === currentUser).map(result => (
                          <div key={result.id} className="p-5 border border-slate-100 rounded-2xl flex justify-between items-center bg-slate-50 hover:bg-white hover:shadow-md transition-all">
                            <div>
                              <p className="font-black text-blue-900">{result.subject}</p>
                              <p className="text-[10px] text-slate-400 font-black uppercase">{result.term}</p>
                            </div>
                            <div className={`text-xl font-black ${result.score >= 50 ? 'text-green-600' : 'text-red-500'}`}>
                              {result.score}%
                            </div>
                          </div>
                        ))
                      )}
                    </div>
                  </div>
                  <div>
                    <h3 className="text-xl font-black text-blue-900 mb-6 font-serif border-b-2 border-slate-50 pb-2">Attendance History</h3>
                    <div className="space-y-3">
                      {state.attendance.filter(a => a.studentId === currentStudentObj?.id).length === 0 ? (
                        <p className="p-8 text-center text-slate-300 font-black uppercase text-[10px] bg-slate-50 rounded-2xl border-2 border-dashed">No attendance records yet</p>
                      ) : (
                        state.attendance.filter(a => a.studentId === currentStudentObj?.id).map((record, i) => (
                          <div key={i} className="p-5 border border-slate-100 rounded-2xl flex justify-between items-center bg-green-50 border-green-100">
                             <div>
                               <p className="font-black text-green-700">Present</p>
                               <p className="text-[10px] text-green-600/60 font-black uppercase">Verified by {record.markedBy}</p>
                             </div>
                             <p className="text-xs font-bold text-green-700">{record.date}</p>
                          </div>
                        ))
                      )}
                    </div>
                  </div>
                </div>
            </div>
          </div>
        )}

        {view === 'teacherLogin' && (
          <TeacherLoginGateway 
            onLogin={handleTeacherLoginAttempt} 
            onBack={() => setView('home')} 
            error={loginError} 
          />
        )}

        {view === 'teacher' && role === UserRole.TEACHER && (
           <div className="max-w-6xl mx-auto py-12 px-4">
             <TeacherDashboard 
               username={currentUser || 'Staff'} 
               assignedGrades={currentTeacherObj?.assignedGrades || []}
               allStudents={state.studentAccounts}
               courses={state.courses}
               results={state.results}
               attendance={state.attendance}
               onAddCourse={addCourse}
               onAddResult={addResult}
               onMarkAttendance={markAttendance}
             />
           </div>
        )}

        {view === 'admin' && (
          role === UserRole.ADMIN ? (
            <div className="max-w-6xl mx-auto py-12 px-4">
              <AdminPanel 
                fees={state.fees} 
                applications={state.applications}
                announcements={state.announcements}
                teachers={state.teachers}
                results={state.results}
                courses={state.courses}
                calendar={state.academicCalendar}
                onUpdateFee={updateFees}
                onAddAnnouncement={addAnnouncement}
                onCreateTeacher={createTeacherAccount}
                onAddCourse={addCourse}
                onUpdateCalendar={updateCalendar}
              />
            </div>
          ) : (
            <AdminLoginGateway 
              onLogin={handleAdminLoginAttempt}
              onBack={() => setView('home')}
              error={loginError}
            />
          )
        )}
      </main>

      <Footer />
    </div>
  );
};

export default App;

import React, { useState, useEffect, useRef } from 'react';
import { Course, StudentResult, GradeLevel, StudentAccount, AttendanceRecord } from '../types';
import { Html5QrcodeScanner } from 'https://esm.sh/html5-qrcode';

interface TeacherDashboardProps {
  username: string;
  assignedGrades: GradeLevel[];
  allStudents: StudentAccount[];
  courses: Course[];
  results: StudentResult[];
  attendance: AttendanceRecord[];
  onAddCourse: (name: string, grade: GradeLevel, description: string) => void;
  onAddResult: (result: Omit<StudentResult, 'id' | 'date' | 'teacherName'>) => void;
  onMarkAttendance: (studentId: string) => boolean;
}

export const TeacherDashboard: React.FC<TeacherDashboardProps> = ({
  username,
  assignedGrades,
  allStudents,
  courses,
  results,
  attendance,
  onAddCourse,
  onAddResult,
  onMarkAttendance
}) => {
  const [activeTab, setActiveTab] = useState<'overview' | 'courses' | 'students' | 'grading' | 'attendance'>('overview');

  // Course form state
  const [courseName, setCourseName] = useState('');
  const [courseGrade, setCourseGrade] = useState<GradeLevel>(assignedGrades[0] || 'Primary 1');
  const [courseDesc, setCourseDesc] = useState('');

  // Grading form state
  const [selectedStudent, setSelectedStudent] = useState<string>('');
  const [selectedSubject, setSelectedSubject] = useState<string>('');
  const [score, setScore] = useState<number>(0);
  const [term, setTerm] = useState<string>('First Term');

  // Scanner status
  const [lastScanned, setLastScanned] = useState<string | null>(null);
  const scannerRef = useRef<Html5QrcodeScanner | null>(null);

  const filteredStudents = allStudents.filter(s => assignedGrades.includes(s.grade));
  const myResults = results.filter(r => r.teacherName === username);
  const today = new Date().toLocaleDateString();
  const presentToday = attendance.filter(a => a.date === today && filteredStudents.some(s => s.id === a.studentId));

  useEffect(() => {
    if (activeTab === 'attendance' && !scannerRef.current) {
      const scanner = new Html5QrcodeScanner(
        "reader", 
        { fps: 10, qrbox: { width: 250, height: 250 } },
        /* verbose= */ false
      );

      scanner.render((decodedText) => {
        if (decodedText.startsWith('GHS-ATT-')) {
          const studentId = decodedText.replace('GHS-ATT-', '');
          const student = allStudents.find(s => s.id === studentId);
          if (student) {
            const success = onMarkAttendance(studentId);
            if (success) {
              setLastScanned(`Success: ${student.name} marked present!`);
              setTimeout(() => setLastScanned(null), 3000);
            } else {
              setLastScanned(`${student.name} already marked today.`);
              setTimeout(() => setLastScanned(null), 3000);
            }
          } else {
            setLastScanned("Error: Invalid Student ID");
            setTimeout(() => setLastScanned(null), 3000);
          }
        }
      }, (error) => {
        // Handle scanning errors silently
      });

      scannerRef.current = scanner;
    }

    return () => {
      if (scannerRef.current && activeTab !== 'attendance') {
        scannerRef.current.clear().catch(err => console.error("Failed to clear scanner", err));
        scannerRef.current = null;
      }
    };
  }, [activeTab]);

  const handleAddCourse = (e: React.FormEvent) => {
    e.preventDefault();
    if (courseName) {
      onAddCourse(courseName, courseGrade, courseDesc);
      setCourseName('');
      setCourseDesc('');
      alert("New course added to curriculum!");
    }
  };

  const handleAddGrade = (e: React.FormEvent) => {
    e.preventDefault();
    const student = allStudents.find(s => s.id === selectedStudent);
    if (student && selectedSubject) {
      onAddResult({
        studentName: student.name,
        grade: student.grade,
        subject: selectedSubject,
        score: score,
        term: term
      });
      setScore(0);
      alert(`Result for ${student.name} recorded!`);
    }
  };

  return (
    <div className="bg-white rounded-[2.5rem] shadow-2xl overflow-hidden border-4 border-yellow-400">
      <div className="bg-blue-900 px-10 py-12 text-white relative">
        <div className="relative z-10">
          <h2 className="text-4xl font-black mb-2 font-serif">Welcome, {username}</h2>
          <div className="flex flex-wrap gap-2 mt-4">
            {assignedGrades.map(g => (
              <span key={g} className="px-3 py-1 bg-yellow-400 text-blue-900 rounded-lg text-[10px] font-black uppercase tracking-tighter shadow-md">
                Class: {g}
              </span>
            ))}
          </div>
          <p className="text-blue-200 font-bold uppercase text-xs tracking-[0.2em] mt-4">Academic Staff Portal • God's Hand School</p>
        </div>
      </div>

      <div className="flex flex-wrap border-b-2 border-slate-100 bg-slate-50">
        {[
          { id: 'overview', label: 'Summary' },
          { id: 'students', label: 'My Students' },
          { id: 'grading', label: 'Grading' },
          { id: 'attendance', label: 'Mark Attendance' },
          { id: 'courses', label: 'Curriculum' }
        ].map(tab => (
          <button 
            key={tab.id}
            onClick={() => setActiveTab(tab.id as any)}
            className={`px-8 py-6 font-black text-sm uppercase tracking-widest transition-all ${activeTab === tab.id ? 'text-blue-900 border-b-4 border-blue-900 bg-white' : 'text-slate-400 hover:text-blue-700'}`}
          >
            {tab.label}
          </button>
        ))}
      </div>

      <div className="p-10">
        {activeTab === 'overview' && (
          <div className="grid md:grid-cols-4 gap-8">
            <div className="p-8 bg-blue-50 rounded-3xl border-2 border-blue-100">
               <p className="text-slate-500 font-bold text-xs uppercase tracking-widest mb-2">My Students</p>
               <p className="text-5xl font-black text-blue-900">{filteredStudents.length}</p>
            </div>
            <div className="p-8 bg-green-50 rounded-3xl border-2 border-green-100">
               <p className="text-slate-500 font-bold text-xs uppercase tracking-widest mb-2">Present Today</p>
               <p className="text-5xl font-black text-green-700">{presentToday.length}</p>
            </div>
            <div className="p-8 bg-yellow-50 rounded-3xl border-2 border-yellow-100">
               <p className="text-slate-500 font-bold text-xs uppercase tracking-widest mb-2">Total Courses</p>
               <p className="text-5xl font-black text-blue-900">{courses.length}</p>
            </div>
            <div className="p-8 bg-indigo-50 rounded-3xl border-2 border-indigo-100">
               <p className="text-slate-500 font-bold text-xs uppercase tracking-widest mb-2">Results Uploaded</p>
               <p className="text-5xl font-black text-blue-900">{myResults.length}</p>
            </div>
          </div>
        )}

        {activeTab === 'attendance' && (
          <div className="grid lg:grid-cols-2 gap-16">
            <div className="space-y-8">
              <h3 className="text-2xl font-black text-blue-900 font-serif">Daily Attendance Scanner</h3>
              <p className="text-slate-500 text-sm font-medium">Use your camera to scan a student's Daily Pass QR code.</p>

              <div id="reader" className="overflow-hidden rounded-3xl border-4 border-slate-100 shadow-xl bg-slate-50 min-h-[300px]"></div>

              {lastScanned && (
                <div className={`p-6 rounded-2xl text-center font-black uppercase tracking-widest animate-pulse ${lastScanned.includes('Success') ? 'bg-green-100 text-green-700' : 'bg-yellow-100 text-yellow-700'}`}>
                  {lastScanned}
                </div>
              )}
            </div>

            <div className="space-y-8">
              <div className="flex justify-between items-center border-b-2 border-slate-100 pb-4">
                <h3 className="text-2xl font-black text-blue-900 font-serif text-nowrap">Present Today</h3>
                <span className="bg-blue-900 text-white px-3 py-1 rounded-full text-[10px] font-black uppercase">{today}</span>
              </div>

              <div className="space-y-4 max-h-[500px] overflow-y-auto pr-2 custom-scrollbar">
                {presentToday.length === 0 ? (
                  <div className="p-12 text-center bg-slate-50 rounded-3xl border-2 border-dashed border-slate-200 text-slate-400 font-bold uppercase text-xs tracking-widest">No attendance recorded for your students yet today.</div>
                ) : (
                  presentToday.map((record, i) => {
                    const student = allStudents.find(s => s.id === record.studentId);
                    return (
                      <div key={i} className="p-5 bg-white border-2 border-slate-50 rounded-2xl flex items-center justify-between shadow-sm">
                        <div className="flex items-center">
                          <div className="w-10 h-10 bg-green-100 text-green-700 rounded-xl flex items-center justify-center font-black mr-4 border border-green-200">
                            {student?.name.charAt(0)}
                          </div>
                          <div>
                            <p className="font-black text-blue-900">{student?.name}</p>
                            <p className="text-[10px] text-slate-400 font-bold uppercase">{student?.grade}</p>
                          </div>
                        </div>
                        <span className="text-[10px] font-black text-green-600 bg-green-50 px-3 py-1 rounded-full uppercase">Verified</span>
                      </div>
                    );
                  })
                )}
              </div>
            </div>
          </div>
        )}

        {activeTab === 'students' && (
          <div className="space-y-8">
            <h3 className="text-2xl font-black text-blue-900 font-serif">Class Registers</h3>
            {assignedGrades.length === 0 ? (
              <div className="p-12 text-center bg-slate-50 rounded-3xl border-2 border-dashed border-slate-200 text-slate-400 font-bold uppercase text-xs tracking-widest">No classes assigned to you yet.</div>
            ) : (
              <div className="grid gap-8">
                {assignedGrades.map(grade => {
                  const studentsInGrade = filteredStudents.filter(s => s.grade === grade);
                  return (
                    <div key={grade} className="bg-white rounded-3xl border-2 border-slate-100 overflow-hidden shadow-sm">
                      <div className="bg-slate-50 px-8 py-4 border-b-2 border-slate-100 flex justify-between items-center">
                        <h4 className="font-black text-blue-900 uppercase tracking-widest">{grade}</h4>
                        <span className="px-3 py-1 bg-blue-900 text-yellow-400 text-[10px] font-black rounded-full">{studentsInGrade.length} Students</span>
                      </div>
                      <div className="divide-y divide-slate-50">
                        {studentsInGrade.length === 0 ? (
                          <p className="p-8 text-center text-slate-400 text-xs font-bold uppercase tracking-widest italic">No students registered in this grade yet.</p>
                        ) : (
                          studentsInGrade.map(student => (
                            <div key={student.id} className="p-6 flex items-center justify-between hover:bg-slate-50 transition-colors">
                              <div className="flex items-center">
                                <div className="w-12 h-12 bg-yellow-100 text-blue-900 rounded-2xl flex items-center justify-center font-black mr-4 border-2 border-yellow-200">
                                  {student.name.charAt(0)}
                                </div>
                                <div>
                                  <p className="font-black text-blue-900 text-lg">{student.name}</p>
                                  <p className="text-xs text-slate-500 font-medium">{student.email}</p>
                                </div>
                              </div>
                              <div className="text-right">
                                <p className="text-[10px] text-slate-400 font-black uppercase tracking-widest mb-1">Enrolled Since</p>
                                <p className="text-xs font-bold text-blue-900">{new Date(student.createdAt).toLocaleDateString()}</p>
                              </div>
                            </div>
                          ))
                        )}
                      </div>
                    </div>
                  );
                })}
              </div>
            )}
          </div>
        )}

        {activeTab === 'grading' && (
           <div className="grid lg:grid-cols-2 gap-16">
              <div>
                <h3 className="text-2xl font-black text-blue-900 mb-8 font-serif">Record Assessment</h3>
                <form onSubmit={handleAddGrade} className="space-y-6 bg-blue-50 p-8 rounded-[2rem] border-2 border-blue-100 shadow-sm">
                  <div className="space-y-2">
                    <label className="text-xs font-black text-blue-900 uppercase tracking-widest">Select Student</label>
                    <select 
                      required
                      value={selectedStudent}
                      onChange={(e) => setSelectedStudent(e.target.value)}
                      className="w-full px-4 py-4 bg-white border-2 border-blue-100 rounded-2xl font-bold outline-none"
                    >
                      <option value="">-- Choose Student --</option>
                      {filteredStudents.map(s => (
                        <option key={s.id} value={s.id}>{s.name} ({s.grade})</option>
                      ))}
                    </select>
                  </div>

                  <div className="space-y-2">
                    <label className="text-xs font-black text-blue-900 uppercase tracking-widest">Subject</label>
                    <select 
                      required
                      value={selectedSubject}
                      onChange={(e) => setSelectedSubject(e.target.value)}
                      className="w-full px-4 py-4 bg-white border-2 border-blue-100 rounded-2xl font-bold outline-none"
                    >
                      <option value="">-- Choose Subject --</option>
                      {courses.map(c => (
                        <option key={c.id} value={c.name}>{c.name} ({c.grade})</option>
                      ))}
                    </select>
                  </div>

                  <div className="grid grid-cols-2 gap-4">
                    <div className="space-y-2">
                      <label className="text-xs font-black text-blue-900 uppercase tracking-widest">Score (0-100)</label>
                      <input 
                        type="number" min="0" max="100" step="any" required
                        value={score}
                        onChange={(e) => setScore(parseFloat(e.target.value) || 0)}
                        className="w-full px-4 py-4 bg-white border-2 border-blue-100 rounded-2xl font-bold outline-none"
                      />
                    </div>
                    <div className="space-y-2">
                      <label className="text-xs font-black text-blue-900 uppercase tracking-widest">Academic Term</label>
                      <select 
                        value={term}
                        onChange={(e) => setTerm(e.target.value)}
                        className="w-full px-4 py-4 bg-white border-2 border-blue-100 rounded-2xl font-bold outline-none"
                      >
                        <option value="First Term">First Term</option>
                        <option value="Second Term">Second Term</option>
                        <option value="Third Term">Third Term</option>
                      </select>
                    </div>
                  </div>

                  <button type="submit" className="w-full py-5 bg-blue-900 text-yellow-400 font-black text-lg rounded-2xl shadow-xl hover:bg-blue-800 transition-all transform hover:-translate-y-1">
                    Upload Result
                  </button>
                </form>
              </div>

              <div className="space-y-6">
                <h3 className="text-2xl font-black text-blue-900 font-serif">Recently Uploaded</h3>
                <div className="space-y-4 max-h-[600px] overflow-y-auto pr-2 custom-scrollbar">
                  {myResults.length === 0 ? (
                    <div className="p-12 text-center bg-white rounded-3xl border-2 border-dashed border-slate-200 text-slate-400 font-bold uppercase text-xs tracking-widest">No results uploaded by you yet.</div>
                  ) : (
                    myResults.map(res => (
                      <div key={res.id} className="p-6 bg-white border-2 border-slate-100 rounded-2xl shadow-sm">
                        <div className="flex justify-between items-start mb-2">
                          <div>
                            <p className="font-black text-blue-900">{res.studentName}</p>
                            <p className="text-[10px] text-slate-400 font-black uppercase tracking-widest">{res.subject} • {res.term}</p>
                          </div>
                          <div className={`text-xl font-black ${res.score >= 50 ? 'text-green-600' : 'text-red-500'}`}>
                            {res.score}%
                          </div>
                        </div>
                      </div>
                    ))
                  )}
                </div>
              </div>
