  onAddAnnouncement: (title: string, content: string) => void;
  onCreateTeacher: (teacher: Omit<TeacherAccount, 'id' | 'createdAt'>) => void;
  onAddCourse: (name: string, grade: GradeLevel, description: string) => void;
  onUpdateCalendar: (content: string) => void;
}

export const AdminPanel: React.FC<AdminPanelProps> = ({ 
  fees, 
  applications, 
  announcements,
  teachers,
  results,
  courses,
  attendance,
  students,
  calendar,
  onUpdateFee,
  onAddAnnouncement,
  onCreateTeacher,
  onAddCourse,
  onUpdateCalendar
}) => {
  const [activeTab, setActiveTab] = useState<'fees' | 'applications' | 'teachers' | 'courses' | 'calendar' | 'announcements' | 'attendance'>('fees');

  // States for forms
  const [annTitle, setAnnTitle] = useState('');
  const [annContent, setAnnContent] = useState('');
  const [teacherUser, setTeacherUser] = useState('');
  const [teacherPass, setTeacherPass] = useState('');
  const [assignedGrades, setAssignedGrades] = useState<GradeLevel[]>([]);
  const [assignedCourses, setAssignedCourses] = useState<string[]>([]);
  const [courseName, setCourseName] = useState('');
