  const handleTeacherSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    if (teacherUser && teacherPass) {
      onCreateTeacher({ 
        username: teacherUser, 
        password: teacherPass,
        assignedGrades,
        assignedCourses
      });
      setTeacherUser('');
      setTeacherPass('');
      setAssignedGrades([]);
      setAssignedCourses([]);
      alert("Staff account created!");
